use vstd::prelude::*;

verus! {

fn array_split(a: Vec<i32>) -> (left: Vec<i32>, right: Vec<i32>)
    ensures
        left@ + right@ == a@,
        left@.len() + right@.len() == a@.len(),
        (a@.len() == 0 ==> left@.len() == 0 && right@.len() == 0),
        (a@.len() == 1 ==> left@.len() == 0 && right@.len() == 1),
        (a@.len() > 1 ==> left@.len() < a@.len() && right@.len() < a@.len()),
{
    let n = a.len();

    // Choose a split point so that:
    // - left.len() + right.len() == n
    // - left ++ right == a
    // - if n > 1, both parts are strictly shorter than n
    let mid = match n {
        0 => 0,
        1 => 0,            // one part will be length 0, the other length 1 (allowed)
        _ => n / 2,        // ensures 1..n-1
    };

    // Facts about `mid` that we will use for slice validity and "strictly shorter" postconditions.
    assert(mid <= n);
    if n > 1 {
        assert(mid >= 1);
        assert(mid < n);
    } else {
        assert(mid == 0);
    }

    let left = a[..mid].to_vec();
    let right = a[mid..].to_vec();

    // Connect slices/to_vec to sequence semantics.
    assert(left@ == a@.subrange(0, mid as int));
    assert(right@ == a@.subrange(mid as int, n as int));
    assert(left@ + right@ == a@);

    (left, right)
}

} // verus!

